"use client";

import { Menu, Bell, HelpCircle, PanelLeftClose, PanelLeftOpen } from "lucide-react";
import ServerClock from "@/components/ui/ServerClock";
import ThemeToggle from "@/components/ui/ThemeToggle";
import UserMenu from "@/components/ui/UserMenu";

interface TopbarProps {
  onMenuToggle: () => void;
  sidebarCollapsed: boolean;
}

export default function Topbar({ onMenuToggle, sidebarCollapsed }: TopbarProps) {
  return (
    <header className="sticky top-0 z-20 flex items-center h-14 px-4 gap-3 bg-[var(--card)] border-b border-[var(--border)] shadow-sm flex-shrink-0">
      {/* ── Left Section ── */}
      <div className="flex items-center gap-2 flex-1 min-w-0">
        {/* Hamburger / Panel toggle button */}
        <button
          onClick={onMenuToggle}
          className="p-2 rounded-lg hover:bg-[var(--accent)] text-[var(--text-muted)] hover:text-[var(--primary)] transition-colors flex-shrink-0"
          aria-label={sidebarCollapsed ? "Buka sidebar" : "Tutup/Kecilkan sidebar"}
          title={sidebarCollapsed ? "Buka sidebar" : "Kecilkan sidebar"}
        >
          {/* Desktop: show panel icon; Mobile: always show hamburger */}
          <span className="hidden lg:block">
            {sidebarCollapsed ? (
              <PanelLeftOpen className="h-5 w-5" />
            ) : (
              <PanelLeftClose className="h-5 w-5" />
            )}
          </span>
          <span className="block lg:hidden">
            <Menu className="h-5 w-5" />
          </span>
        </button>

        {/* Divider */}
        <div className="h-6 w-px bg-[var(--border)] flex-shrink-0" />

        {/* Server date/time clock */}
        <ServerClock />
      </div>

      {/* ── Right Section ── */}
      <div className="flex items-center gap-1.5 flex-shrink-0">
        {/* Theme toggle */}
        <ThemeToggle />

        {/* Divider */}
        <div className="h-6 w-px bg-[var(--border)] mx-1" />

        {/* Help button */}
        <button
          className="p-2 rounded-lg hover:bg-[var(--accent)] text-[var(--text-muted)] hover:text-[var(--primary)] transition-colors"
          aria-label="Bantuan"
          title="Bantuan"
        >
          <HelpCircle className="h-5 w-5" />
        </button>

        {/* Notification bell */}
        <button
          className="relative p-2 rounded-lg hover:bg-[var(--accent)] text-[var(--text-muted)] hover:text-[var(--primary)] transition-colors"
          aria-label="Notifikasi"
          title="Notifikasi"
        >
          <Bell className="h-5 w-5" />
          <span className="absolute top-1.5 right-1.5 w-2 h-2 bg-red-500 rounded-full border-2 border-[var(--card)]" />
        </button>

        {/* Divider */}
        <div className="h-6 w-px bg-[var(--border)] mx-1" />

        {/* User info + dropdown */}
        <UserMenu />
      </div>
    </header>
  );
}
